// === Tab: Softy ===
class Softy {
	constructor(x, y, r, n, v = 0.75) {
		this.x = x;
		this.y = y;
		this.r = r;
		this.n = n; // number of edges
		this.v = v; // variation radii (multiplier [0..1])
		this.ct = random(-5, 5); // random(-1, 0.5); // https://p5js.org/reference/p5/curveTightness/
		this.rot = random(TAU);
		this.calcPts();
		this.cDelta = random(palette.length); // delta for clr
		this.cNsDiv = random(111, 444); // noise devider for clr
		this.cIxInc = random(0.001, 0.01); // color range index inc
	}

	calcPts() {
		this.pts = [];
		const da = TAU/this.n/2;
		for (let i = 0; i < this.n; i++) {
			const f = i/this.n;
			const na = noise(this.x, this.y, frameCount/88) - 0.5; // -0.5 ... 0.5
			const a = TAU * f + da * na;
			const ns = noise(this.x + this.y, a, frameCount/123) - 0.5; // -0.5 ... 0.5
			const dr = this.r * ns;
			const r = this.r + dr * this.v;

			const x = cos(a) * r;
			const y = sin(a) * r;
			this.pts.push({x, y});
		}
	}

	update() {
		const nr = noise(this.x, this.y, frameCount/234) - 0.5;
		this.rot += nr / 8;
		const nt = noise(this.y, frameCount/123, this.x) - 0.5;
		this.ct = 10 * nt;
		this.calcPts();
	}

	collides(o) {
		if (Array.isArray(o)) {
			for (let other of o) {
				if (this.collides(other)) return true;
			}
			return false;
		} else {
			return dist(this.x, this.y, o.x, o.y) < this.r + o.r;
		}
	}

	show() {
		push();
		let dx = 0, dy = 0;
		if (~~this.x % 2 === 0) {
			dx = sin(frameCount/this.cNsDiv*10) * this.r * 0.2;
		} else {			
			dy = cos(frameCount/this.cNsDiv*10) * this.r * 0.2;
		}
		translate(this.x + dx, this.y + dy);
		rotate(this.rot);
		curveTightness(this.ct);
		fill(this.getNoiseClr());
		beginShape();
		for (let i = 0; i < this.pts.length + 3; i++) {
			const p = this.pts[i % this.pts.length]
			curveVertex(p.x, p.y);
		}
		endShape();
		pop();
	}

	getNoiseClr() {
		const n = noise(frameCount/this.cNsDiv, this.x, this.y) + (this.cDelta += this.cIxInc);
		return getClrFromPalette(palette, n, 100);
	}
}

