	function getClrFromPalette(palette, fr, al = 0) { 
		const ci = fr * palette.length;
		const clr1 = color(palette[(~~ci+0) % palette.length]); 
		const clr2 = color(palette[(~~ci+1) % palette.length]);
		if (al) {
			clr1.setAlpha(al);
			clr2.setAlpha(al);
		}
		return lerpColor(clr1, clr2, fract(ci));
