const USE_SVG = false;
let objs, palette;

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);
	noFill();
	noStroke();
	palette = random(palettes);
	objs = [];
	loop();
}

function draw() {
	insertSofty();
	background(32);
	background(getClrFromPalette(palette, frameCount/234, 25));

	for (let o of objs) {
		o.update();
		o.show();
	}
}

function mousePressed() {
	if (mouseButton !== RIGHT) setup();
}

function insertSofty() {
	var a = random(TAU);
	const dst = random(random()) * max(width, height) * 0.5;
	var x = cos(a) * dst + width/2; // randomGaussian(width / 2, 150);
	var y = sin(a) * dst + height/2; // randomGaussian(height / 2, 150);
	var r = random(0.01, 0.1) * max(width, height);
	var n = ~~random(3, 11);
	newObj = new Softy(x, y, r, n);
	if (!newObj.collides(objs)) {
		objs.push(newObj);
	}
}
